function S(v){return v==null?'':String(v).trim();}
function esc(s){return S(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

var BASE='https://old-hub.example/webhook';
var HUB=BASE+'/cbs-admin';

/* ------------------------------------------------------------------
   FOLDER BUCKETS - the ONE place to change how a folder routes.
   Compared lower case against the ServiceM8 queue (folder) name.
   ------------------------------------------------------------------ */
var ENQUIRY = ['enquiry','estimated'];
var JOBFILE = ['reactive (call-out)','maintenance','approved','part approved','awaiting client','works completed','part invoiced'];
var BLOCKED = ['on hold','ss rsd inv qb'];

function head(title){
  return '<!doctype html><html lang="en-GB"><head><meta charset="utf-8">'
  +'<meta name="viewport" content="width=device-width,initial-scale=1">'
  +'<title>'+esc(title)+'<'+'/title><style>'
  +':root{color-scheme:light}*{box-sizing:border-box}'
  +'body{margin:0;background:#f3f2ef;color:#161616;font:15px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif}'
  +'header{display:flex;gap:14px;align-items:center;justify-content:space-between;flex-wrap:wrap;padding:14px 18px;background:#3d4043;color:#fff}'
  +'header h1{margin:0;font-size:19px;font-weight:700}'
  +'header .sub{display:block;margin-top:2px;font-size:13px;font-weight:400;opacity:.82}'
  +'.hbtns{display:flex;gap:8px;flex-wrap:wrap}'
  +'.hbtn{padding:9px 14px;border-radius:9px;border:1px solid rgba(255,255,255,.35);background:transparent;color:#fff;font:inherit;font-size:14px;font-weight:600;text-decoration:none;cursor:pointer}'
  +'.hbtn.primary{background:#F47920;border-color:#F47920;color:#161616}'
  +'main{max-width:620px;margin:0 auto;padding:22px 18px 40px}'
  +'.card{background:#fff;border:1px solid #e0ddd7;border-radius:12px;padding:20px}'
  +'.big{display:block;width:100%;min-height:62px;padding:17px 20px;margin:0 0 8px;background:#F47920;color:#161616;font:inherit;font-size:18px;font-weight:700;text-align:left;border:0;border-radius:13px;cursor:pointer}'
  +'.big:disabled{opacity:.55;cursor:default}'
  +'.hint{margin:0 0 18px;padding:0 4px;font-size:14px;line-height:1.4;color:#6c6a66}'
  +'.note{padding:16px 18px;background:#fff;border-left:4px solid #F47920;border-radius:10px;font-size:16px;line-height:1.5}'
  +'<'+'/style><'+'/head><body>';
}

function hdr(h,sub,extra){
  return '<header><h1>'+esc(h)+(sub?'<span class="sub">'+esc(sub)+'<'+'/span>':'')+'<'+'/h1>'
  +'<div class="hbtns">'+(extra||'')+'<a class="hbtn" href="'+esc(HUB)+'">Back to hub<'+'/a><'+'/div><'+'/header>';
}

function page(body){ return [{json:{b:body+'<'+'/body><'+'/html>'}}]; }

function go(url){
  return [{json:{b:'<!doctype html><html lang="en-GB"><head><meta charset="utf-8">'
  +'<meta http-equiv="refresh" content="0;url='+esc(url)+'">'
  +'<'+'/head><body><'+'script>location.replace('+JSON.stringify(url)+')<'+'/script><'+'/body><'+'/html>'}}];
}

function notFound(){
  return page(head('Job not found')+hdr('Job not found','','')
  +'<main><div class="note">Could not find this job in ServiceM8. Refresh to try again.<'+'/div><'+'/main>');
}

/* The Job File page deep links itself: its script runs
   show(hash==="#enquiry"||(mode==="none"&&...)?"enquiry":"file")
   so #enquiry forces the Enquiry tab and no hash lands on the Job File tab
   once a job file exists. Nothing in CBS - Job File needs changing. */
function jobFile(no,tab){
  return BASE+'/cbs-job-file?job='+encodeURIComponent(no)+(tab==='enquiry'?'#enquiry':'');
}

function blocked(no,where,hasRow){
  var extra=hasRow?('<a class="hbtn primary" href="'+esc(BASE+'/cbs-job-file?job='+encodeURIComponent(no))+'">Open job record<'+'/a>'):'';
  return page(head('Job '+no)+hdr('Job '+no,where,extra)
  +'<main><div class="note">This job is in <strong>'+esc(where||'no folder')+'<'+'/strong>, so there is nothing to prepare here. '
  +'Enquiry prep is for jobs in Enquiry or Estimated, and the job file opens once a job is approved, reactive or maintenance.'
  +(hasRow?' Use <strong>Open job record<'+'/strong> above to look at it.':'')
  +'<'+'/div><'+'/main>');
}

/* ---------------- route ---------------- */
var J=null;
try{J=$('AD Job').all().map(function(i){return i.json;}).filter(function(x){return x&&x.uuid;})[0]||null;}catch(e){}
var no=J?S(J.generated_job_id).replace(/^#/,''):'';
if(!no) return notFound();

var Q={};
try{$('AD Queues').all().forEach(function(i){var x=i.json;if(x&&x.uuid)Q[S(x.uuid)]=S(x.name);});}catch(e){}
var folder=Q[S(J.queue_uuid)]||'';
var status=S(J.status);
/* ServiceM8 shows some jobs by status rather than folder; the hub labels those
   "Booked / on site". Use whichever we have when naming the job's position. */
var where=folder||status;

var H=null;
try{H=$('AD Hub').all().map(function(i){return i.json;})
  .filter(function(x){return x&&S(x.ref).replace(/^#/,'').toLowerCase()===no.toLowerCase();})[0]||null;}catch(e){}
var mode=S(H&&H.mode).toLowerCase();
var hasFile=(mode==='project'||mode==='cdm'||mode==='closed');

var f=folder.toLowerCase();
var bucket = ENQUIRY.indexOf(f)>=0 ? 'enquiry'
           : (JOBFILE.indexOf(f)>=0 ? 'file'
           : (BLOCKED.indexOf(f)>=0 ? 'blocked' : 'unknown'));

if(bucket==='enquiry') return go(jobFile(no,'enquiry'));

/* No Create Project / Create CDM screen any more: a job with no Job File opens the job page (Enquiry tab),
   where Create Job File (or Approved) asks for the type. */
if(bucket==='file'){
  if(hasFile) return go(jobFile(no,'file'));
  return go(jobFile(no,'enquiry'));
}

/* Unrecognised or missing folder: never block real work. If the hub already
   holds a job file, open it. Folders listed in BLOCKED still block. */
if(bucket==='unknown' && hasFile) return go(jobFile(no,'file'));

return blocked(no,where,!!H);

